parameters.jsCode:
const response = $input.first().json;
const appointments = response.data || [];

const today = new Date().toLocaleDateString('en-ZA', {
  weekday: 'long', day: 'numeric', month: 'long'
});

if (appointments.length === 0) {
  return [{ json: { message: `📅 Good morning Doctor!\n\nNo appointments scheduled for today (${today}).\n\nHave a great day! 😊` } }];
}

const lines = appointments.map((apt, i) => {
  const payment = apt.payment_method === 'medical_aid'
    ? `${apt.medical_aid || ''}${apt.medical_plan ? ' (' + apt.medical_plan + ')' : ''}`
    : 'Cash';
  return `${i + 1}. ${apt.time} — ${apt.patient_name}\n   💬 ${apt.reason_for_visit || apt.reason || 'No reason given'}\n   💳 ${payment}\n   📌 ${apt.status === 'confirmed' ? '✅ Confirmed' : '⏳ Pending'}`;
});

const message = `📅 Good morning Doctor!\n\nSchedule for ${today}:\n${appointments.length} appointment${appointments.length === 1 ? '' : 's'}\n\n${lines.join('\n\n')}\n\nHave a productive day! 💪`;

return [{ json: { message } }];

